// lib/precedents/library/willsEstatesDepth.ts
// Wills, estate planning and estate administration in depth: will variants,
// testamentary trusts, capacity, superannuation death benefits, contested
// estates, and the administration documents that arise once a grant issues.
//
// Succession law is STATE-based. Where a document turns on state statute --
// the dispensing power for informal wills, statutory wills, notices of
// intended distribution, transmission applications, family provision -- the
// precedent prompts for the applicable Act rather than assuming NSW.
//
// Superannuation is the significant exception: death benefits are governed
// by the SIS Act and the fund's trust deed, are federal, and pass OUTSIDE
// the estate unless directed to it. That is the single most common gap
// between what a client thinks their will does and what it actually does,
// which is why it has its own precedent here.
import { text, field, type PrecedentSeed } from "./types";

const WILLS = ["Wills & Estates"];

